import { createReadStream } from 'node:fs';
import { mkdir, rm, stat, writeFile } from 'node:fs/promises';
import path from 'node:path';
import type { Readable } from 'node:stream';

/**
 * Where uploaded files live. Keys are generated by the server (never taken from a client), so they can
 * be trusted as file names. To move to S3 / Cloudflare R2 / any object store, add another class that
 * implements this interface and pick it in `createStorage`; nothing else in the app changes.
 */
export interface Storage {
  put(key: string, data: Buffer, contentType: string): Promise<void>;
  /** A readable stream, or null when the file does not exist. */
  open(key: string): Promise<{ stream: Readable; size: number } | null>;
  delete(key: string): Promise<void>;
}

const SAFE_KEY = /^[a-z0-9][a-z0-9/_-]*\.[a-z0-9]{2,5}$/;

/** Files on this server's disk. Fine for one server; for several servers or serverless use an object store. */
export class LocalDiskStorage implements Storage {
  constructor(private readonly root: string) {}

  private pathFor(key: string): string {
    if (!SAFE_KEY.test(key) || key.includes('..')) {
      throw new Error('Unsafe storage key.');
    }
    return path.join(this.root, key);
  }

  async put(key: string, data: Buffer): Promise<void> {
    const file = this.pathFor(key);
    await mkdir(path.dirname(file), { recursive: true });
    await writeFile(file, data);
  }

  async open(key: string) {
    const file = this.pathFor(key);
    try {
      const info = await stat(file);
      return { stream: createReadStream(file), size: info.size };
    } catch {
      return null;
    }
  }

  async delete(key: string): Promise<void> {
    await rm(this.pathFor(key), { force: true });
  }
}

export function createStorage(uploadsDir: string): Storage {
  return new LocalDiskStorage(path.resolve(uploadsDir));
}
